  const processFile = (file: File | undefined) => {
    if (!file) return;

    // Validate types: PDF, Text, or Images
    const validTypes = ['application/pdf', 'text/plain', 'image/png', 'image/jpeg', 'image/webp'];
    if (!validTypes.includes(file.type)) {
