import { RubricData } from '../types';

/**
 * Validates if the rubric has all necessary fields populated.
 * Checks for:
 * 1. At least one criterion.
 * 2. Non-empty Criterion Title.
 * 3. Non-empty Criterion Description.
 * 
 * Returns an error message string if invalid, or null if valid.
 */
export const validateRubric = (rubric: RubricData): string | null => {
  if (!rubric || !rubric.criteria || rubric.criteria.length === 0) {
    return "Rubrika neturi jokių kriterijų.";
  }

  for (let i = 0; i < rubric.criteria.length; i++) {
    const criterion = rubric.criteria[i];

    // Check Criterion Title
    if (!criterion.title || criterion.title.trim() === "") {
      return `Kriterijus #${i + 1} neturi pavadinimo. Google Classroom importui pavadinimas yra privalomas.`;
    }

    // Check Criterion Description (Requested by user)
    if (!criterion.description || criterion.description.trim() === "") {
      return `Kriterijus "${criterion.title}" neturi aprašymo. Prašome įrašyti aprašymą.`;
    }
  }

  return null;
};

