import React, { useState, useEffect } from 'react';
import { GoogleLogin } from '@react-oauth/google';
import { jwtDecode } from 'jwt-decode';
import { getAuth, signOut } from "firebase/auth";
import { app } from './firebaseConfig';
import { generateClassroomCSV } from './classroomCSVGenerator';

function App() {
  const [user, setUser] = useState(null);
  const [driveStatus, setDriveStatus] = useState('');
  const [file, setFile] = useState(null);

  const auth = getAuth(app);

  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('user', JSON.stringify(user));
    } else {
      localStorage.removeItem('user');
    }
  }, [user]);

  const handleLoginSuccess = async (response) => {
    const decoded = jwtDecode(response.credential);
    setUser(decoded);
  };

  const handleLoginError = (error) => {
    console.error('Login Failed', error);
  };

  const handleSignOut = () => {
    signOut(auth).then(() => {
      setUser(null);
      localStorage.removeItem('user');
    }).catch((error) => {
      console.error("Sign-out error", error);
    });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setFile(file);
  };


  const uploadToDrive = async () => {
    if (!file) {
      alert("Please select a file to upload.");
      return;
    }

    if (!user) {
      alert("Please log in to upload.");
      return;
    }

    const accessToken = user.access_token;

    const metadata = {
      name: file.name,
      mimeType: 'text/csv'
    };

    const form = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', file);

    const uploadUrl = 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart';

    try {
      setDriveStatus('Įkeliama...');

      const res = await fetch(uploadUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${accessToken}`,
          'Content-Type': 'multipart/form-data'
        },
        body: form
      });

      if (!res.ok) {
        let errorMessage = `Upload failed: ${res.statusText}`;
        try {
            const errorBody = await res.json();
            if (errorBody?.error?.message) {
                errorMessage += ` (${errorBody.error.message})`;
            }
        } catch (ignore) {
            // Fallback to statusText only
        }
        throw new Error(errorMessage);
      }
      setDriveStatus('Failas sėkmingai įkeltas! šsaugota!');
      setTimeout(() => setDriveStatus(''), 3000);

    } catch (e) {
      console.error('Upload error', e);
      // alert(`Nepavyko įkelti failo į Google Drive: ${e.message}`);
      alert(e.message)
      setDriveStatus('');
    }
  };


  return (
    <div className="App">
      <h1>Google Drive Upload</h1>
      {user ? (
        <div>
          <p>Logged in as: {user.name}</p>
          <button onClick={handleSignOut}>Sign out</button>
          <input type="file" onChange={handleFileChange} />
          <button onClick={uploadToDrive}>Upload to Drive</button>
          {driveStatus && <p>{driveStatus}</p>}
        </div>
      ) : (
        <GoogleLogin onSuccess={handleLoginSuccess} onError={handleLoginError} />
      )}
    </div>
  );
}

